import {infectionOffer,infectCustomer} from './infection.js';
import {moveStaff} from './staff.js';
import {visitorPath} from './visitors.js';
import {createDiagnostics,setDiagnostics,installErrorHandlers,reportError} from './diagnostics.js';
import {cafeSize} from './world.js';
import {createCatalog} from './catalog.js';
import {createOfflineService} from './offline-service.js';
import {nextGameSpeed,setGameSpeed,applyStartingLayout,furnitureRotation,rotateFurniture,entranceAccess,setCafeOpen,CATALOG,configureOriginalCatalog,GOALS,initialState,reconcile,startCooking,serve,place,move,claim,levelOf,validateSave} from './model.js';
import {CafeScene,loadSceneAssets} from './scene.js';
const BUILD='zombie-body-head-composition-1';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={star:'m12 3 2.7 5.5 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1L3.2 9.4l6.1-.9Z',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',pot:'M5 10h14v7a3 3 0 0 1-3 3H8a3 3 0 0 1-3-3Z M3 10h18 M9 6V3m6 3V3M2 13h3m14 0h3',book:'M12 5v15M12 5C8 2 5 3 3 4v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-2-1-5-2-9 1',chair:'M6 13V3h12v10M4 13h16v4H4Zm2 4v4m12-4v4',people:'M9 7a3 3 0 1 1-6 0 3 3 0 0 1 6 0M20 8a3 3 0 1 1-6 0 3 3 0 0 1 6 0M1 20v-3a5 5 0 0 1 10 0v3m2 0v-2a5 5 0 0 1 9 0v2',focus:'M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M10 2h4l1 3 3 1 3 3-1 3 1 3-3 3-3 1-1 3h-4l-1-3-3-1-3-3 1-3-1-3 3-3 3-1Z',sound:'M4 9h4l5-4v14l-5-4H4Zm13-2a8 8 0 0 1 0 10m3-13a12 12 0 0 1 0 16',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0m-2 4 6 6'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.star}"/></svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
let catalog,catalogPreferences={},offline,recipes,state,scene,selectedStove,selectedFurniture=null,selectedZombie=null,tab='recipes',filter='foryou',search='',placement=null,modalRecipe=null,saveError=false,lastLevel=1,toastTimer;
let storage;try{storage=window.localStorage;}catch{}
let saveBlocked=false,simulationFailed=false;
const diagnostics=createDiagnostics({storage,build:BUILD,context:()=>({tab,speed:state?.speed,saveBlocked,simulationFailed,visitors:state?.visitors?.people.length,staff:state?.staff?.people.map(z=>({id:z.id,phase:z.phase,targetId:z.targetId})),stoves:state?.stoves.map(s=>({id:s.id,recipeId:s.job?.recipeId,remaining:s.job?.remaining})),online:navigator.onLine}),notify:entry=>{
 const banner=$('#error-notice');banner.hidden=false;$('#error-summary').textContent='Café error ('+entry.source+'): '+entry.message+'. Diagnostics are available below.';
}});
setDiagnostics(diagnostics);installErrorHandlers(window,diagnostics);
function tick(){if(simulationFailed)return;try{return reconcile(state);}catch(error){simulationFailed=true;saveBlocked=true;reportError(error,'simulation paused; automatic saving stopped');}}
function downloadDiagnostics(){const url=URL.createObjectURL(new Blob([diagnostics.snapshot()],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='zombie-cafe-diagnostics.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copyDiagnostics(){try{await navigator.clipboard.writeText(diagnostics.snapshot());toast('Diagnostics copied.');}catch(error){reportError(error,'copy diagnostics');downloadDiagnostics();toast('Could not copy; downloaded diagnostics instead.');}}
$('#download-diagnostics').onclick=downloadDiagnostics;$('#dismiss-error').onclick=()=>$('#error-notice').hidden=true;
document.addEventListener('click',event=>{const button=event.target.closest('button');if(button)diagnostics.mark(button.id||Object.keys(button.dataset).map(key=>key+':'+button.dataset[key]).join(' ')||'button');},true);
const format=n=>Math.round(n).toLocaleString();
function duration(seconds){if(!Number.isFinite(seconds))return 'Paused';seconds=Math.max(0,Math.ceil(seconds));if(seconds>=3600)return Math.floor(seconds/3600)+'h '+Math.floor(seconds%3600/60)+'m';if(seconds>=60)return Math.floor(seconds/60)+'m '+(seconds%60?seconds%60+'s':'');return seconds+'s';}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function saveView(){if(!offline||!scene)return;offline.saveView({tab,filter,search,selectedStove,zoom:scene.targetZoom,pan:scene.pan,catalog:catalogPreferences});}
function save(){if(saveBlocked){$('#save-status').textContent='Automatic saving stopped · see diagnostics';return;}try{offline.save(state);saveView();saveError=false;$('#save-status').textContent='Saved on this device';}catch(error){reportError(error,'save');if(!saveError)toast('Could not save the café. Export a backup and diagnostics from Options.');saveError=true;$('#save-status').textContent='Not saved · export from Settings';}}
function after(result){if(result?.message)toast(result.message);save();renderHUD();renderStations();renderPanel();refreshModal();}
function switchTab(name){$('.side-panel').hidden=false;$('.side-panel').dataset.panel=name;tab=name;document.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.tab===name);b.tabIndex=b.dataset.tab===name?0:-1;});$('#panel-content').setAttribute('aria-labelledby','tab-'+name);renderPanel();}
function renderHUD(){
 const diners=state.visitors?.people.filter(g=>!['passing','approaching'].includes(g.phase)&&g.y>=0).length||0;$('#guest-count').textContent=diners+' diners · '+Math.round((state.visitors?.rating??.5)*100)+'% popularity';
 $('#coins').textContent=format(state.coins);$('#toxin').textContent=format(state.toxin||0);$('#level').textContent=levelOf(state);$('#xp-fill').style.width=(state.xp%20)/20*100+'%';$('#level-title').textContent=levelOf(state)>=5?'Afterlife institution':levelOf(state)>=3?'Neighborhood haunt':levelOf(state)>=2?'Rising from the grave':'Graveyard rookie';
 $('#speed-label').textContent='Game speed · '+state.speed+'×';$('#game-speed-value').textContent=state.speed+'×';const speedHelp='Game speed: '+(state.speed===0?'paused':state.speed+'×')+'. Click for '+(nextGameSpeed(state.speed)===0?'pause':nextGameSpeed(state.speed)+'×')+'.';$('#game-speed').setAttribute('aria-label',speedHelp);$('#game-speed').title=speedHelp;$('#game-speed').querySelectorAll('[data-speed-step]').forEach(p=>p.classList.toggle('active',Number(p.dataset.speedStep)<=state.speed));$('#cafe-name').innerHTML=esc(state.name)+'<span class="title-dot">.</span>';
 const portions=state.stock.reduce((n,b)=>n+b.quantity,0);$('#stock-count').textContent=portions?portions+' portions to serve':"Kitchen’s warming up";
 $('#goal-dot').hidden=!GOALS.some(g=>!state.claimed.includes(g.id)&&state.stats[g.stat]>=g.target);$('#kitchen-count').textContent=state.stoves.length+' cooking stations';
 const access=entranceAccess(state);$('#entrance-status').dataset.warning=String(access.doorBlocked||access.blocked.length>0);$('#door-toggle').textContent=state.doorOpen?'Close café':'Open café';$('#door-toggle').setAttribute('aria-pressed',String(state.doorOpen));$('#entrance-status').textContent=access.doorBlocked?'Door blocked: move the furniture in front of the entrance.':access.blocked.length?'Blocked paths: keep the door, chairs, serving counters and sink connected.':state.doorOpen?'Café open':'Café closed · cooking continues';
 $('#sound').classList.toggle('music-on',!state.muted);$('#sound').setAttribute('aria-label',state.muted?'Turn music on':'Turn music off');
 if(state.stats.cooked>0)$('#chef-tip').textContent=portions?'Your guests are tucking in. Keep the next batch cooking!':'An empty counter is a lonely counter. Pick a recipe and fire up a stove.';
 if(levelOf(state)>lastLevel){toast('Level '+levelOf(state)+'! More questionable delicacies await.');renderPanel();}lastLevel=levelOf(state);
}
function renderStations(){const active=document.activeElement?.dataset?.station;
 $('#stations').innerHTML=state.stoves.map((st,i)=>{const r=st.job&&recipes.find(r=>r.id===st.job.recipeId),ready=st.job&&st.job.remaining<=0;return `<button class="station ${ready?'ready':''} ${selectedStove===st.id?'selected':''}" data-station="${st.id}" aria-label="Station ${i+1}: ${r?esc(r.name)+(ready?', ready to serve':', cooking'):'empty, choose recipe'}"><span class="station-top"><span>STATION 0${i+1}</span><span class="station-status">${ready?'● READY':r?'● COOKING':'○ EMPTY'}</span></span><span class="station-body">${r?`<img src="assets/recipes/${r.field_0x14}.png" alt="">`:`<span class="empty-pot">${icon('pot')}</span>`}<span><strong>${r?esc(r.name):'Something tasty?'}</strong><small>${ready?'Waiting for zombie pickup':r?(state.speed===0?'Paused':duration(st.job.remaining/state.speed)+' remaining'):'Choose a recipe + '}</small></span></span>${r&&!ready?`<span class="station-progress"><i style="width:${Math.max(0,Math.min(100,(1-st.job.remaining/st.job.total)*100))}%"></i></span>`:''}</button>`;}).join('');
 if(active)document.querySelector(`[data-station="${active}"]`)?.focus({preventScroll:true});
}
function recipeCards(){let list=recipes.filter(r=>!search||r.name.toLowerCase().includes(search.toLowerCase()));if(filter==='foryou'&&!search)list=[...list].sort((a,b)=>Math.max(1,a.field_0x16)-Math.max(1,b.field_0x16)||a.id-b.id).slice(0,8);
 return list.length?list.map(r=>{const locked=Math.max(1,r.field_0x16)>levelOf(state);return `<button class="recipe-card ${locked?'locked':''}" data-recipe="${r.id}" aria-label="${esc(r.name)}, ${locked?'unlocks at level '+r.field_0x16:r.baseCost+' coins'}"><span class="recipe-art"><span class="recipe-duration">${duration(r.cookMinutes*60)}</span><img src="assets/recipes/${r.field_0x14}.png" alt="" loading="lazy"></span><span class="recipe-info"><strong>${esc(r.name)}</strong><span class="servings">${r.baseServings} servings per batch · ${r.baseXp} XP</span><span class="recipe-price">${locked?`Level ${r.field_0x16}`:`<span><span class="mini-coin">◉</span>${format(r.baseCost)} / batch</span>`}<b>${locked?'LOCKED':'COOK ↗'}</b></span></span></button>`;}).join(''):'<div class="empty-state">No recipes found. Try another name.</div>';
}
function renderRecipeGrid(){const g=$('#recipe-grid');if(g)g.innerHTML=recipeCards();}
function renderPanel(){if(!state)return;if(tab==='store'){catalog?.refresh();return;}const content=$('#panel-content'),scroll=content.scrollTop;
 if(tab==='recipes')content.innerHTML=`<div class="panel-heading"><h2>The recipe book</h2><span>234 RECIPES</span></div><p class="panel-subtitle">Made with love. And a few other things.</p><button class="button small secondary" data-move="${esc(selectedStove)}">Move selected stove</button><div class="search-field">${icon('search')}<input id="recipe-search" type="search" placeholder="Find something delicious…" aria-label="Search recipes" value="${esc(search)}"></div><div class="recipe-filters"><button class="filter-chip ${filter==='foryou'?'active':''}" data-filter="foryou">For you</button><button class="filter-chip ${filter==='all'?'active':''}" data-filter="all">All recipes</button></div><div id="recipe-grid" class="recipe-grid">${recipeCards()}</div>${state.stock.length?`<div class="stock-list"><h3>On the serving counter</h3>${state.stock.slice(0,6).map(b=>`<div class="stock-row"><span>${esc(recipes.find(r=>r.id===b.recipeId)?.name)}</span><span>${b.quantity} left</span></div>`).join('')}</div>`:''}`;
 if(tab==='decorate'){const f=state.furniture.find(f=>f.id===selectedFurniture),item=placement?.itemId&&CATALOG.find(c=>c.id===placement.itemId);content.innerHTML=`<div class="panel-heading"><h2>Decorate</h2><span>YOUR CAFÉ</span></div><p class="panel-subtitle">A little charm goes a long way. Even here.</p><div class="floor-options">${[2,5,29].map(id=>`<button class="floor-button ${state.floor===id?'active':''}" data-floor="${id}" aria-label="${id===2?'Cherry':id===5?'Black':'Gray'} checkerboard floor"><img src="assets/furniture/${id}.png" alt=""></button>`).join('')}</div>${f&&!placement?`<div class="selection-info"><strong>Selected: ${esc(CATALOG.find(c=>c.sprite===f.sprite)?.name||f.kind)}</strong><p>${furnitureRotation(f).label}</p>${f.kind==='chair'?`<p>Faces ${['southeast','northwest','southwest','northeast'][f.direction??3]}. A table must be directly in front.</p>`:''}<div class="action-row"><button class="button small secondary" data-move="${f.id}">Move</button><button class="button small secondary" data-rotate="${f.id}" ${furnitureRotation(f).count===1?'disabled':''}>${furnitureRotation(f).count===1?'Fixed orientation':furnitureRotation(f).count===4?'Rotate ↻ · 4 directions':'Turn ↔ · 2 directions'}</button></div></div>`:''}${placement?`<div class="selection-info"><strong>${item?'Place '+esc(item.name):'Move your furniture'}</strong><p>Tap an empty café tile, or choose a location below.</p><div class="tile-picker"><label>Column<select id="tile-x">${Array.from({length:cafeSize(state).width},(_,i)=>`<option value="${i}">${i+1}</option>`).join('')}</select></label><label>Row<select id="tile-y">${Array.from({length:cafeSize(state).height},(_,i)=>`<option value="${i}">${i+1}</option>`).join('')}</select></label><button class="button small" id="place-tile">Place</button></div><button class="button small secondary" id="cancel-panel-placement">Cancel placement</button></div>`:''}<div class="shop-grid">${[].map(c=>`<button class="shop-card" data-buy="${c.id}" aria-label="Buy ${esc(c.name)} for ${c.cost} coins"><img src="assets/furniture/${c.sprite}.png" alt="" loading="lazy"><strong>${esc(c.name)}</strong><span>◉ ${c.cost} <span style="float:right">+</span></span></button>`).join('')}</div>`;}
 if(tab==='goals')content.innerHTML=`<div class="panel-heading"><h2>Orders</h2><span>NIGHT ONE</span></div><p class="panel-subtitle">Every legendary diner starts with a first bite.</p>${GOALS.map((g,i)=>{const complete=state.stats[g.stat]>=g.target,claimed=state.claimed.includes(g.id);return `<article class="goal-card ${complete?'complete':''} ${claimed?'claimed':''}"><div class="goal-number">0${i+1} / ${claimed?'DONE':complete?'NICE WORK':'YOUR NEXT LITTLE WIN'}</div><h3>${g.title}</h3><p>${g.description}</p><div class="goal-track"><i style="width:${Math.min(100,state.stats[g.stat]/g.target*100)}%"></i></div><div class="goal-reward"><span>${Math.min(g.target,state.stats[g.stat])} / ${g.target}</span><span>◉ ${g.coins} + ${g.xp} XP</span></div><button class="button small ${complete&&!claimed?'lime':'secondary'}" data-claim="${g.id}" ${!complete||claimed?'disabled':''}>${claimed?'✓ Reward collected':complete?'Collect reward':'In progress'}</button></article>`;}).join('')}`;
 content.insertAdjacentHTML('afterbegin','<button class="original-panel-close" id="panel-close" aria-label="Close panel">×</button>');content.scrollTop=scroll;
}
function setPlacement(p){selectZombie(null);placement=p;scene.placement=p;$('#placement-banner').hidden=!p;$('#placement-copy').textContent=p?(p.moveId?'Pick a new spot':'Pick an empty tile'):'';switchTab('decorate');}
function onPlace(x,y){if(!placement)return;const result=placement.moveId?move(state,placement.moveId,x,y):place(state,placement.itemId,x,y);if(result.ok)setPlacement(null);after(result);}
function selectZombie(id){selectedZombie=id;scene.selectedZombie=id;$('#zombie-controls').hidden=!id;if(id){placement=null;scene.placement=null;$('#placement-banner').hidden=true;selectedFurniture=null;scene.selected=null;$('.side-panel').hidden=true;$('#world').focus({preventScroll:true});}}
function directZombie(cell){tick();after(moveStaff(state,selectedZombie,cell,visitorPath));}
function showCustomer(id){
 const offer=infectionOffer(state,id);selectZombie(null);modalRecipe=null;
 const price=offer.rule?offer.rule.cost===0?'Free':format(offer.rule.cost)+' '+(offer.rule.currency==='toxin'?'toxin vials':'coins'):'';
 openDialog('<div class="eyebrow">RECRUIT A WORKER</div><h2>'+esc(offer.customer?.name||'Customer')+'</h2><p>Infect this customer to turn them into a permanent zombie worker. They will help serve food and clean tables. '+(state.infectionTutorialComplete?'':'For your first infection, the chef must reach the customer first.')+'</p><p>Workers: '+state.staff.people.length+' / '+(offer.cap||'—')+'</p><p>'+esc(offer.ok?'Infection cost: '+price:offer.message)+'</p><button class="button lime" id="infect-customer" '+(offer.ok?'':'disabled')+'>Infect'+(price?' · '+esc(price):'')+'</button>');
 $('#infect-customer').onclick=()=>{const result=infectCustomer(state,id);closeDialog();after(result);};
}
function onSelect(id,cell){if(typeof id==='string'&&id.startsWith('customer-')){showCustomer(Number(id.slice(9)));return;}if(state.staff.people.some(z=>z.id===id)){selectZombie(selectedZombie===id?null:id);return;}if(selectedZombie){if(cell)directZombie(cell);return;}selectedFurniture=id;scene.selected=id;const stove=state.stoves.find(s=>s.id===id);if(stove){selectedStove=id;if(stove.job?.remaining===0)after(serve(state,id,recipes));else{switchTab('recipes');renderStations();toast(stove.job?'This batch has '+duration(stove.job.remaining/state.speed)+' left.':'Choose a recipe for station '+(state.stoves.indexOf(stove)+1)+'.');}}else if(id)switchTab('decorate');else if(tab==='decorate')renderPanel();}
function openDialog(html,options=false){$('#modal').classList.toggle('options-dialog',options);$('#modal').classList.toggle('recipe-details',modalRecipe!==null);$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function openRecipe(id){modalRecipe=id;const r=recipes.find(r=>r.id===id);openDialog(`<div class="eyebrow">FROM THE RECIPE BOOK</div><h2>${esc(r.name)}</h2><div class="food-detail"><img src="assets/recipes/${r.field_0x14}.png" alt="${esc(r.name)}"><div><p>Ingredients</p><strong>◉ ${format(r.baseCost)} coins</strong><p style="margin-top:8px">${duration(r.cookMinutes*60/state.speed)} in this shift</p></div></div><div class="food-stats"><div><strong>${r.baseServings}</strong><small>servings per batch</small></div><div><strong>${r.baseSellPrice}</strong><small>coins earned per serving</small></div><div><strong>${r.baseXp}</strong><small>XP per batch</small></div></div><p class="muted-note">Full batch sales: ◉ ${format(r.baseServings*r.baseSellPrice)} · Profit after ingredients: ◉ ${format(r.baseServings*r.baseSellPrice-r.baseCost)} if every serving sells.</p><p id="recipe-lock"></p><div class="dialog-stoves" id="dialog-stoves"></div><p class="muted-note">${state.speed===0?'Game time is paused.':state.speed>1?'Game time runs '+state.speed+'× faster.':'Game time runs at real time.'} Zombies carry finished batches to empty counters, then serve guests one portion at a time.</p>`);refreshModal();}
function refreshModal(){if(!$('#modal').open||modalRecipe===null)return;const r=recipes.find(r=>r.id===modalRecipe),locked=Math.max(1,r.field_0x16)>levelOf(state);$('#recipe-lock').textContent=locked?'This recipe unlocks at level '+r.field_0x16+'.':state.coins<r.baseCost?'You need '+format(r.baseCost-state.coins)+' more coins.':'Choose an empty cooking station:';const focus=document.activeElement?.dataset?.cook;$('#dialog-stoves').innerHTML=state.stoves.map((st,i)=>`<button data-cook="${st.id}" ${locked||st.job||state.coins<r.baseCost?'disabled':''}><span>Station 0${i+1}${selectedStove===st.id?' · selected':''}</span><span>${st.job?st.job.remaining<=0?'Ready to serve':state.speed===0?'Paused':duration(st.job.remaining/state.speed)+' left':'Start cooking ↗'}</span></button>`).join('');if(focus)document.querySelector(`[data-cook="${focus}"]`)?.focus({preventScroll:true});}
function closeDialog(){modalRecipe=null;$('#modal').close();}
function settings(){modalRecipe=null;openDialog(`<div class="eyebrow">MAKE YOURSELF AT HOME</div><h2>Options</h2><label class="field">Café name<input id="name-input" maxlength="40" value="${esc(state.name)}"></label><button class="button small secondary" id="rename" style="margin-top:10px">Save name</button><p>Cooking uses the original recipe durations.</p><div class="setting-row"><div><strong>Music</strong><p>The original Zombie Café theme.</p></div><button class="button small secondary" id="settings-sound">${state.muted?'Off':'On'}</button></div><p class="muted-note">Your café saves automatically in this browser. Export a backup to move it to another device. Away progress is calculated for up to 8 hours.</p><div class="settings-actions"><button class="button secondary" id="export-save">Export save</button><button class="button secondary" id="import-save">Import save</button><button class="button secondary" id="original-layout">Original starting layout</button><button class="button secondary" id="restore-layout-backup">Restore layout backup</button><button class="button danger" id="reset-save">New café</button></div><input type="file" id="import-file" accept="application/json,.json"><p class="muted-note">This browser edition uses its own save format. Android saves are not supported.</p><h3>Debugging</h3><p class="muted-note">Errors and recent actions stay on this device. Diagnostics include stack traces and game status, not your full save.</p><div class="settings-actions"><button class="button secondary" id="copy-diagnostics">Copy diagnostics</button><button class="button secondary" id="export-diagnostics">Download diagnostics</button></div><p class="muted-note">Build: ${BUILD}</p>`,true);}
function resumeMusic(){if(state&&!state.muted){$('#music').volume=.22;$('#music').play().catch(()=>{});}}
document.addEventListener('pointerdown',resumeMusic,{once:true});
document.addEventListener('keydown',resumeMusic,{once:true});
async function toggleMusic(){const audio=$('#music');audio.volume=.22;if(state.muted){try{await audio.play();state.muted=false;}catch{toast('Music could not start. Please try again.');return;}}else{audio.pause();state.muted=true;}save();renderHUD();if($('#settings-sound'))$('#settings-sound').textContent=state.muted?'Off':'On';}
function toggleSpeed(){after(setGameSpeed(state,nextGameSpeed(state.speed)));if(modalRecipe!==null)openRecipe(modalRecipe);}
function exportSave(){reconcile(state);const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='zombie-cafe-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Café backup exported.');}
function about(){modalRecipe=null;openDialog(`<div class="about-logo"><img src="assets/chef.png" alt=""></div><div class="eyebrow">SAME APPETITE. A NEW HOME.</div><h2>Welcome back to<br>Zombie Café.</h2><p>An offline browser recreation using the original loading screens, artwork, skeletal animations, music, and 234 recovered recipes.</p><h3>Make this little diner yours.</h3><p>Cook, serve, earn coins, decorate, and save your progress. Quick shift makes the wait a little shorter.</p><h3>Still waking up.</h3><p>Original character animations and the full recovered art catalog are now available. Customer behavior, progression, tutorial, raids and special-item systems still require faithful ports. Android save imports are not available yet.</p><h3>With gratitude to the original creators.</h3><p>Zombie Café was originally created by Beeline Interactive and CAPCOM. This community-driven recompilation is a tribute to the game we all loved, built with care to preserve its spirit and respect the work of its original creators.</p><p class="muted-note">An unofficial fan project, not affiliated with or endorsed by the original creators. All original game assets belong to their respective owners.</p><button class="button lime full" id="back-game">Back to the kitchen</button>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!state)return;
 if(b.dataset.tab){switchTab(b.dataset.tab);return;}if(b.dataset.filter){filter=b.dataset.filter;renderPanel();return;}if(b.dataset.recipe){openRecipe(Number(b.dataset.recipe));return;}
 if(b.dataset.station){selectedStove=b.dataset.station;scene.selected=selectedStove;const st=state.stoves.find(s=>s.id===selectedStove);if(st.job?.remaining===0)after(serve(state,st.id,recipes));else{switchTab('recipes');renderStations();if(st.job)openRecipe(st.job.recipeId);else toast('Station '+(state.stoves.indexOf(st)+1)+' selected. Choose a recipe.');}return;}
 if(b.dataset.cook){const r=recipes.find(r=>r.id===modalRecipe),result=startCooking(state,b.dataset.cook,r);if(result.ok)closeDialog();after(result);return;}
 if(b.dataset.buy){const item=CATALOG.find(c=>c.id===b.dataset.buy);if(state.coins<item.cost){toast('You need '+(item.cost-state.coins)+' more coins for this piece.');return;}setPlacement({itemId:item.id});toast('Pick an empty tile for your '+item.name.toLowerCase()+'.');return;}
 if(b.dataset.move){setPlacement({moveId:b.dataset.move});return;}if(b.dataset.rotate){const f=state.furniture.find(f=>f.id===b.dataset.rotate);if(f)after(rotateFurniture(f));return;}
 if(b.dataset.floor){state.floor=Number(b.dataset.floor);state.floorChanged=true;after({ok:true,message:'A fresh look, on the house.'});return;}if(b.dataset.claim){after(claim(state,b.dataset.claim));return;}
 switch(b.id){
 case 'door-toggle':after(setCafeOpen(state,!state.doorOpen));break;
 case 'panel-close':$('.side-panel').hidden=true;break;
 case 'enter-cafe':$('#original-title').hidden=true;resumeMusic();break;
 case 'home-screen':$('#original-title').hidden=false;break;
 case 'nav-recipes':switchTab('recipes');break;
 case 'nav-store':case 'nav-characters':tab=b.id==='nav-store'?'store':'characters';$('.side-panel').hidden=tab==='store';$('.side-panel').dataset.panel=tab;catalog.open(tab);break;
 case 'nav-goals':switchTab('goals');break;
 case 'nav-options':case 'title-options':settings();break;
 case 'done-zombie':selectZombie(null);break;case 'cancel-placement':case 'cancel-panel-placement':setPlacement(null);break;
 case 'place-tile':onPlace(Number($('#tile-x').value),Number($('#tile-y').value));break;
 case 'zoom-in':scene.setZoom(.12);break;case 'zoom-out':scene.setZoom(-.12);break;case 'zoom-reset':scene.setZoom(0);break;
 case 'settings':settings();break;case 'sound':case 'settings-sound':toggleMusic();break;case 'game-speed':case 'speed':case 'settings-speed':toggleSpeed();break;
 case 'close-modal':case 'back-game':closeDialog();break;case 'about':about();break;
 case 'rename':state.name=$('#name-input').value.trim()||'The Midnight Diner';after({ok:true,message:'Welcome to '+state.name+'.'});break;
 case 'copy-diagnostics':copyDiagnostics();break;case 'export-diagnostics':downloadDiagnostics();break;case 'export-save':exportSave();break;case 'import-save':$('#import-file').click();break;
 case 'original-layout':localStorage.setItem('zombie-cafe.before-original-layout',JSON.stringify(state));applyStartingLayout(state);selectedStove=state.stoves[0].id;selectedFurniture=null;scene.selected=null;setPlacement(null);closeDialog();after({ok:true,message:'Original starting layout applied. Previous café backed up on this device.'});break;
 case 'restore-layout-backup':{const raw=localStorage.getItem('zombie-cafe.before-original-layout');if(raw){state=validateSave(JSON.parse(raw),recipes);scene.state=state;selectedStove=state.stoves[0].id;selectedFurniture=null;closeDialog();after({ok:true,message:'Previous café restored.'});}else toast('No layout backup yet.');break;}
 case 'reset-save':openDialog('<div class="eyebrow">A FRESH START</div><h2>Open a new café?</h2><p>This replaces your current café and progress in this browser. Export your save first if you want to keep it.</p><div class="settings-actions"><button class="button secondary" id="keep-cafe">Keep my café</button><button class="button danger" id="confirm-reset">Start fresh</button></div>');break;
 case 'keep-cafe':settings();break;
 case 'confirm-reset':saveBlocked=false;simulationFailed=false;$('#music').pause();state=initialState();scene.state=state;selectedStove=state.stoves[0].id;selectedFurniture=null;lastLevel=1;setPlacement(null);closeDialog();switchTab('recipes');after({ok:true,message:'The original café is ready for its first recipe.'});break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='recipe-search'){search=e.target.value;renderRecipeGrid();}});
document.addEventListener('change',async e=>{if(e.target.id==='import-file'&&e.target.files[0]){const file=e.target.files[0];try{if(file.size>2e6)throw Error('The save file is too large.');const incoming=validateSave(JSON.parse(await file.text()),recipes);modalRecipe=null;openDialog('<div class="eyebrow">CAFÉ BACKUP FOUND</div><h2>Restore this café?</h2><p>This will replace your current browser progress with '+esc(incoming.name)+'.</p><div class="settings-actions"><button class="button secondary" id="keep-cafe">Cancel</button><button class="button lime" id="confirm-import">Restore café</button></div>');$('#confirm-import').onclick=()=>{state=incoming;saveBlocked=false;simulationFailed=false;reconcile(state);$('#music').pause();resumeMusic();scene.state=state;selectedStove=state.stoves[0].id;selectedFurniture=null;lastLevel=levelOf(state);setPlacement(null);closeDialog();switchTab('recipes');after({ok:true,message:'Café restored. Welcome back!'});};}catch(err){reportError(err,'import save');toast('Could not import save: '+err.message);}}});
const chatInput=$('#chat-input'),chatMessages=$('#chat-messages');
$('#chat-form').addEventListener('submit',event=>{
 event.preventDefault();
 const message=chatInput.value.trim();
 if(!message){chatInput.focus();return;}
 $('#chat-empty')?.remove();
 const entry=document.createElement('p'),author=document.createElement('strong');
 author.textContent='You: ';entry.append(author,document.createTextNode(message));chatMessages.append(entry);
 while(chatMessages.children.length>100)chatMessages.firstElementChild.remove();
 chatMessages.scrollTop=chatMessages.scrollHeight;chatInput.value='';chatInput.focus();
});
document.addEventListener('keydown',e=>{
 if(e.defaultPrevented||e.isComposing)return;
 if(e.target.closest('input,textarea,select,[contenteditable]:not([contenteditable="false"])')){
  if(e.target===chatInput&&e.key==='Escape'){e.preventDefault();$('#world').focus({preventScroll:true});}
  return;
 }
 if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!document.querySelector('dialog[open]')&&$('#original-title').hidden&&$('#original-loading').hidden){e.preventDefault();chatInput.focus({preventScroll:true});return;}
 if(selectedZombie){if(e.key==='Escape'){selectZombie(null);return;}if(e.target.id==='world'){const z=state.staff.people.find(z=>z.id===selectedZombie),p=scene.hover||{x:Math.round(z.x),y:Math.round(z.y)},d={ArrowRight:[1,0],ArrowLeft:[-1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(d){e.preventDefault();scene.hover={x:Math.max(0,Math.min(cafeSize(state).width-1,p.x+d[0])),y:Math.max(0,Math.min(cafeSize(state).height-1,p.y+d[1]))};toast('Column '+(scene.hover.x+1)+', row '+(scene.hover.y+1)+'. Enter to move zombie.');return;}if(e.key==='Enter'){e.preventDefault();directZombie(p);return;}}}if(e.key==='Escape'&&placement)setPlacement(null);if(e.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const tabs=['recipes','decorate','goals'];switchTab(tabs[(tabs.indexOf(tab)+(e.key==='ArrowRight'?1:2))%3]);$('#tab-'+tab).focus();}if(e.target.id==='world'&&placement){let p=scene.hover||{x:0,y:7};const keys={ArrowRight:[1,0],ArrowLeft:[-1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(keys[e.key]){e.preventDefault();p={x:Math.max(0,Math.min(7,p.x+keys[e.key][0])),y:Math.max(0,Math.min(7,p.y+keys[e.key][1]))};scene.hover=p;toast('Column '+(p.x+1)+', row '+(p.y+1)+'. Press Enter to place.');}if(e.key==='Enter'){e.preventDefault();onPlace(p.x,p.y);}}});
$('#modal').addEventListener('close',()=>{modalRecipe=null;});
document.addEventListener('visibilitychange',()=>{if(state){tick();save();}});window.addEventListener('pagehide',()=>{if(state)save();});
async function boot(){try{
 $('#original-load-status').textContent='Loading recipes and store…';
 const [original,recipeData]=await Promise.all(['assets/original/furniture-data.json','assets/recipes.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw Error('Game data unavailable: '+url+' (HTTP '+r.status+')');return r.json();})));configureOriginalCatalog(original.items);recipes=recipeData;
 if(!storage)throw Error('Browser storage is unavailable. Allow local storage and reload.');offline=createOfflineService(storage,recipes);
 const entry=offline.request('/v170/jpfiles/getEntry.php');
 const shop=offline.request('/pco/zombie/azcjp/v170/getGameInfo.php');
 if(entry.status!==200||shop.status!==200)throw Error('Offline service unavailable');
 let restoreMessage='';try{state=offline.load()||initialState();}catch(error){saveBlocked=true;reportError(error,'load save');state=initialState();restoreMessage='Previous save could not load. It has been preserved; automatic saving is stopped. Import a backup or explicitly start a new café in Options.';}
 const view=offline.loadView();tab=view.tab;filter=view.filter;search=view.search;catalogPreferences=view.catalog||{};
 const away=reconcile(state);lastLevel=levelOf(state);selectedStove=state.stoves.find(s=>!s.job)?.id||state.stoves[0].id;
 $('#original-load-status').textContent='Loading furniture and characters…';
 scene=new CafeScene($('#world'),state,await loadSceneAssets(state,recipes),onSelect,onPlace,()=>after(setCafeOpen(state,!state.doorOpen)),tick,saveView);scene.zoom=scene.targetZoom=view.zoom;scene.pan=view.pan;
 if(state.stoves.some(s=>s.id===view.selectedStove))selectedStove=view.selectedStove;
 catalog=createCatalog({container:$('#panel-content'),storeDialog:$('#store-modal'),assets:scene.assets,getState:()=>state,onClose:()=>{$('.side-panel').hidden=true;},onBuy:item=>{if(['floor','wall'].includes(item.kind)){after(place(state,item.id,0,0));catalog.refresh();}else{catalog.closeStore();setPlacement({itemId:item.id});toast('Choose a tile for '+item.name+'.');}},preferences:catalogPreferences,onRemember:value=>{catalogPreferences=value;save();}});
 $('#scene-loading').hidden=true;renderHUD();renderStations();if(!['store','characters'].includes(tab))switchTab(tab);$('.side-panel').hidden=true;save();
 $('#original-loading').hidden=true;$('#original-title').hidden=false;$('#enter-cafe').textContent=state.stats.cooked?'CONTINUE':'PLAY';
 resumeMusic();
 setTimeout(startOfflineCache,1500);
 if(restoreMessage)toast(restoreMessage);else if(away.earned&&away.elapsed>60)toast('Welcome back! Your café earned '+away.earned+' coins while you were away.');
 let priorReady=state.stoves.filter(s=>s.job?.remaining===0).length,priorServed=state.stats.served;
 setInterval(()=>{tick();if(simulationFailed)return;const ready=state.stoves.filter(s=>s.job?.remaining===0).length,result={sold:state.stats.served-priorServed};priorServed=state.stats.served;renderHUD();renderStations();refreshModal();if(ready>priorReady)toast('Order up! A zombie will carry the batch to an empty counter.');priorReady=ready;save();if(tab==='goals'&&result.sold)renderPanel();if(result.sold&&$('.stock-list')){if(!state.stock.length)$('.stock-list').remove();else $('.stock-list').innerHTML='<h3>On the serving counter</h3>'+state.stock.slice(0,6).map(b=>'<div class="stock-row"><span>'+esc(recipes.find(r=>r.id===b.recipeId)?.name)+'</span><span>'+b.quantity+' left</span></div>').join('');}},1000);
 }catch(error){saveBlocked=true;reportError(error,'startup');$('#original-load-status').textContent='Could not load the café: '+error.message+'. Reload to retry.';$('#scene-loading').innerHTML='<div style="text-align:center;padding:25px">The kitchen couldn’t open.<br><small style="font:12px system-ui">'+esc(error.message)+'</small><br><button class="button" onclick="location.reload()" style="margin-top:16px">Try again</button></div>';console.error(error);}}
document.addEventListener('click',()=>{if(state)save();});
document.addEventListener('input',()=>{if(state)save();});
boot();
// Wait until gameplay assets are ready before downloading the offline collection.
function startOfflineCache(){if(!('serviceWorker' in navigator))return;
 window.addEventListener('online',()=>navigator.serviceWorker.controller?.postMessage('cache-game'));
 navigator.serviceWorker.addEventListener('message',event=>{if(event.data==='offline-ready')$('#save-status').textContent='Saved on this device · offline ready';else if(event.data?.type==='cache-error')reportError(new Error(event.data.message),'offline cache');else if(event.data==='cache-ready')event.source?.postMessage('cache-game');});
 navigator.serviceWorker.register('./sw.js').then(registration=>{if(!registration.installing)registration.active?.postMessage('cache-game');}).catch(error=>reportError(error,'offline cache registration'));
}
